-- ── admin_bulk_set_study_notes_published(text,uuid[],boolean) ───
CREATE OR REPLACE FUNCTION public.admin_bulk_set_study_notes_published(p_caller text, p_ids uuid[], p_published boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_count int;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;

  update study_notes set is_published = p_published, updated_at = now()
  where id = any(p_ids);
  get diagnostics v_count = row_count;

  return json_build_object('ok', true, 'updated', v_count);
end;
$function$;

-- ── admin_cancel_subscription(text,text) ────────────────────────
CREATE OR REPLACE FUNCTION public.admin_cancel_subscription(p_caller text, p_user_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN

  perform assert_verified_admin(p_caller);  -- P0.5
  IF NOT EXISTS (SELECT 1 FROM admins WHERE uid = p_caller AND is_active = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE subscriptions
  SET status = 'cancelled', updated_at = now()
  WHERE user_id = p_user_id;
END;
$function$;

-- ── admin_change_passcode(text,text,text) ───────────────────────
CREATE OR REPLACE FUNCTION public.admin_change_passcode(p_caller text, p_target_uid text, p_passcode text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO v_role FROM admins WHERE uid = p_caller AND is_active = true;
  IF v_role IS DISTINCT FROM 'superadmin' THEN
    RETURN json_build_object('error', 'Unauthorized');
  END IF;
  IF length(p_passcode) <> 6 OR p_passcode !~ '^\d{6}$' THEN
    RETURN json_build_object('error', 'Passcode must be 6 digits');
  END IF;
  UPDATE admins
     SET passcode_hash = encode(sha256(p_passcode::bytea), 'hex'),
         updated_at    = NOW()
   WHERE uid = p_target_uid;
  RETURN json_build_object('ok', true);
END;
$function$;

