-- ── admin_update_user(text,text,jsonb) ──────────────────────────
CREATE OR REPLACE FUNCTION public.admin_update_user(p_caller text, p_target_uid text, p_fields jsonb)
 RETURNS users
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_row public.users;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;
  update public.users set
    display_name = coalesce(p_fields->>'display_name', display_name),
    target_exam  = coalesce(p_fields->>'target_exam', target_exam),
    syllabus     = coalesce(p_fields->>'syllabus', syllabus),
    class_level  = coalesce(p_fields->>'class_level', class_level)
  where firebase_uid = p_target_uid
  returning * into v_row;
  return v_row;
end; $function$;

-- ── admin_upsert_email_template(text,text,text,text,text,text,text,text[],text,text,text) 
CREATE OR REPLACE FUNCTION public.admin_upsert_email_template(p_caller text, p_template_key text, p_label text, p_description text, p_subject text, p_heading text, p_body_text text, p_bullet_points text[], p_button_label text, p_button_path text, p_footer_note text)
 RETURNS email_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row email_templates;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  IF NOT EXISTS (SELECT 1 FROM admins WHERE uid = p_caller AND is_active = true) THEN
    RAISE EXCEPTION 'Unauthorized';
